# This formula is regenerated by the ankra-cli release workflow from
# packaging/homebrew/ankra.rb.tmpl in ankraio/ankra-cli. Manual edits here
# will be overwritten on the next release; change the template instead.
#
# There is deliberately no `version` stanza: `brew audit` fails a tap whose
# declared version it can already scan from the stable URL (redundant_version),
# and every release URL below carries the tag. That is why the URLs interpolate
# nothing - the release workflow substitutes the version into them directly.
class Ankra < Formula
  desc "Command-line interface for the Ankra Kubernetes platform"
  homepage "https://ankra.io"
  license "Apache-2.0"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.20.0/ankra-cli-darwin-arm64"
      sha256 "915120798d65c351afddfc4f399b9081b7a64084ffc8cbc298a55e3b4ab3ea89"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.20.0/ankra-cli-darwin-amd64"
      sha256 "e8f802e7081756957fff19e4d5a2a5e621e52fa75b54375d8df3fd8edc97db30"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.20.0/ankra-cli-linux-arm64"
      sha256 "eed74a9bb8513ec4e358e82475e7d07b9446e2192ebba204cc86718505169993"
    end
    on_intel do
